// Generates src/types/api.generated.ts from the API's OpenAPI description.
//
//   npm run gen:api                       (the local dev API at http://localhost:5156)
//   KINODEX_OPENAPI=<url or file> npm run gen:api
//
// The API serves its description at /openapi/v1.json in development, so run the API first.
// Re-run this after changing a backend model, then commit the regenerated files; TypeScript
// then points at anything in the frontend that no longer matches.
//
// It also saves the description itself as src/types/openapi.json. A backend test compares that
// with the API's current description, so forgetting to re-run this fails `dotnet test`.
import { readFileSync, writeFileSync } from "node:fs";
import openapiTS, { astToString } from "openapi-typescript";

const source = process.env.KINODEX_OPENAPI ?? "http://localhost:5156/openapi/v1.json";
const typesDir = new URL("../src/types/", import.meta.url);

const text = /^https?:\/\//.test(source)
  ? await (await fetch(source)).text()
  : readFileSync(source, "utf8");
const document = JSON.parse(text);
// The address the API happened to run on; not part of the API itself
delete document.servers;

writeFileSync(new URL("openapi.json", typesDir), JSON.stringify(document, null, 2) + "\n");

const ast = await openapiTS(document);
const banner =
  "// Generated by scripts/gen-api-types.mjs from the API's OpenAPI description. Don't edit by\n" +
  "// hand: change the backend model, then run `npm run gen:api`.\n\n";
writeFileSync(new URL("api.generated.ts", typesDir), banner + astToString(ast));
console.log(`Wrote src/types/api.generated.ts and openapi.json from ${source}`);
